import{z as i,x as p,o as t,c as B,q as s,j as o,D as E,d as r,s as n,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"HTAP","description":"","frontmatter":{"title":"HTAP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/htap.md","filePath":"cs/htap.md","lastUpdated":1791063341000}'),d={name:"cs/htap.md"};function C(P,a,T,D,m,h){const l=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="htap" tabindex="-1">HTAP <a class="header-anchor" href="#htap" aria-label="Permalink to &quot;HTAP&quot;">​</a></h1><div class="epigraph"><p>同一份（或可对齐快照的）数据既要短事务又要扫描分析。引擎用双格式、双集群或可更新列存，隔离的是资源与新鲜度合同。</p><footer>—— 据 Özcan et al. HTAP 综述；C-Store/HyPer 谱系；OLTP-OLAP 边界</footer></div><p><a href="/cs/storage-compute-separation">上一课</a>让计算弹性。本课不挂盘。缺口是工作负载混合：OLTP 要点查与索引，OLAP 要列扫。传统做法 ETL 到数仓，新鲜度小时级。HTAP（Hybrid Transactional/Analytical Processing）要秒级或事务级新鲜。分布式序列接近收口，NewSQL 下一课归产品族。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一条缓冲池、一种页格式难同时最优。路径：① 行存主 + 异步列副本（CDC）；② 可更新列存 + delta；③ 内存行 + 列批次（HyPer 热切）；④ 存算分离上两计算引擎读同一 WAL。缺口是<strong>新鲜度、隔离、资源隔离</strong>：分析扫打爆 OLTP 缓冲，2Q 抗扫描不够还要 QoS、WLM。</p><p><span class="marginnote">术语翻译：OLTP 是「一笔一笔办业务」——收银、转账，每次碰几行、要求毫秒响应；OLAP 是「月底翻全年账本做盘点」——一次扫几亿行、只要吞吐不要即时。HTAP 就是让同一份数据同时支撑这两种活法，难点在两种活法的最优数据格式相反。</span></p><p>快照：分析用只读快照不挡 OLTP 写，但 GC 水位或列副本延迟仍在。</p><p><span class="marginnote">HTAP 一词工业界常用。HyPer 热切、TiFlash 列副本质是工程点。本课合同不是商标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明 SLA：分析可落后 \\(x\\) 秒。路由：短查询走行，扫走列。物化视图在 HTAP 里当列侧预聚合。计划：同一 SQL 两套代价模型。</p><p>与 shuffle：列侧 MPP 仍要连接。事务写只打行侧，列侧追。</p>',11)),(t(),o(A,null,{default:E(()=>[n(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22OLTP%20%E5%86%99%22%5D%20--%3E%20ROW%5B%22%E8%A1%8C%E5%BC%95%E6%93%8E%22%5D%0A%20%20ROW%20--%3E%20CDC%5B%22%E5%A4%8D%E5%88%B6%20%2F%20delta%22%5D%0A%20%20CDC%20--%3E%20COL%5B%22%E5%88%97%E5%BC%95%E6%93%8E%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20ROUTE%5B%22%E6%8C%89%E5%BD%A2%E7%8A%B6%E8%B7%AF%E7%94%B1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"一致性：最强是同一 MVCC 戳两引擎可读；常见是列落后。读己之写：刚写去列侧可能没有，要路由到行或等。TDE 两份。vacuum 与列 compaction 双重 GC。",-1)),a[5]||(a[5]=e("p",null,"校准：两套 I/O。计划回归：优化器突然把 OLTP 语句送到列扫。",-1)),a[6]||(a[6]=e("p",null,"刚写进行的数据，为什么在列侧可能查不到？按新鲜度路由看：",-1)),(t(),o(A,null,{default:E(()=>[n(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20SNAP%5B%22%E6%9F%A5%E5%88%97%E4%BE%A7%E5%BF%AB%E7%85%A7%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20SNAP%20--%3E%20F%7B%22%E8%A6%81%E7%9A%84%E6%95%B0%E6%8D%AE%E5%B7%B2%E8%BF%9B%E5%88%97%E5%89%AF%E6%9C%AC%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20COL%5B%22%E5%88%97%E5%BC%95%E6%93%8E%E6%89%AB%E6%8F%8F%22%5D%0A%20%20F%20--%3E%7C%22%E5%90%A6%EF%BC%88%E8%AF%BB%E5%B7%B1%E4%B9%8B%E5%86%99%EF%BC%89%22%7C%20R%7B%22%E5%90%88%E5%90%8C%E5%85%81%E8%AE%B8%E8%90%BD%E5%90%8E%20x%20%E7%A7%92%EF%BC%9F%22%7D%0A%20%20R%20--%3E%7C%E8%83%BD%E7%AD%89%7C%20COL%0A%20%20R%20--%3E%7C%E4%B8%8D%E8%83%BD%E7%AD%89%7C%20ROW%5B%22%E5%9B%9E%E9%80%80%E8%A1%8C%E5%BC%95%E6%93%8E%E6%9F%A5%E8%AF%A2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">数字实例：传统 ETL 到数仓，新鲜度是小时级；HTAP 的 CDC 列副本把它压到秒级。若合同写「分析可落后 5 秒」，那刚下的订单 3 秒后就跑报表，走列侧没问题；要求「下单一秒后必须查到」，这类查询就得路由回行侧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列举 NewSQL 商标列表——下一课分类。也不把 HTAP 当向量数据库。湖仓后课是分析侧文件，新鲜度更松。</p><p>后课默认：混合负载要双路径或明确落后。NewSQL：SQL+分布式事务+分片的产品标签。</p><p>没有资源隔离的「一个库扛 HTAP」会把 2Q 与 latch 热点一起打穿。</p><p><span class="marginnote">常见误区：初学者容易以为「合到一个库就万事大吉」。实际上没有资源隔离时，一条全表扫描的分析查询能占满缓冲池与 I/O，让前台收银事务一起排队——就像让盘点员和收银员共用一张桌子，盘点一展开，结账全堵死。QoS、WLM 这类配额机制是 HTAP 的必需品，不是可选项。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HTAP 用双格式或双引擎对齐新鲜度与资源。</li><li>分析快照与 OLTP 写的水位要合同。</li><li>NewSQL 下一课。</li><li>出处：HTAP 综述；HyPer/C-Store；CDC。</li></ul>',8))])}const L=i(d,[["render",C]]);export{u as __pageData,L as default};
